parameters.jsCode:
const items = $input.all();

let phq9 = '';
let gad7 = '';
let sintomas = '';
let riesgo = '';
let factores = '';
let seguimiento = '';

items.forEach(item => {
  // Es un resultado del vector store
  if (item.json.document) {
    const doc = item.json.document;
    const seccion = doc.metadata?.seccion || '';
    const contenido = doc.pageContent || '';

    if (seccion.includes('phq9')) phq9 += contenido + '\n\n';
    else if (seccion.includes('gad7')) gad7 += contenido + '\n\n';
    else if (seccion.includes('sintomas')) sintomas += contenido + '\n\n';
    else if (seccion.includes('cssrs') || seccion.includes('riesgo')) riesgo += contenido + '\n\n';
    else if (seccion.includes('factores') || seccion.includes('comorbilidad')) factores += contenido + '\n\n';
  }

  // Es un resultado del nodo Supabase (sesiones anteriores)
  if (item.json.fecha) {
    const fecha = new Date(item.json.fecha).toLocaleDateString('es-ES', { day:'2-digit', month:'short', year:'numeric' });
    const linea = `Sesión ${fecha} | PHQ-9: ${item.json.phq9 ?? '—'} (${item.json.severidad_depresion ?? '—'}) | GAD-7: ${item.json.gad7 ?? '—'} (${item.json.severidad_ansiedad ?? '—'}) | Ideación: ${item.json.ideacion_suicida ?? '—'}`;
    seguimiento += linea + '\n';
  }
});

return [{
  json: {
    contexto_phq9: phq9,
    contexto_gad7: gad7,
    contexto_sintomas: sintomas,
    contexto_riesgo: riesgo,
    contexto_factores: factores,
    seguimiento: seguimiento || 'Primera sesión — sin historial previo.'
  }
}];

